const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let importing=false;
let presets={},items=[],selected=null,currentRole='sticker_static',busy=false,img=null,imageGeneration=0,drag=null;
const canvas=$('#canvas'),ctx=canvas.getContext('2d');const size=n=>n>=1e6?(n/1e6).toFixed(2)+' MB':(n/1000).toFixed(1)+' KB';
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500)}
async function checkConnection(){
 try{let r=await Pocket.fetch('/api/health',{cache:'no-store',signal:AbortSignal.timeout(5000)});if(!r.ok)throw Error('连接失败');let info=await r.json();if(info.service!=='pixel-pocket')throw Error('服务不匹配');TOKEN=info.token;$('#connection').textContent='● 浏览器处理已就绪';$('#connection').className='note online';return true}
 catch(e){$('#connection').textContent='图片引擎未就绪，请稍候或刷新重试。';$('#connection').className='note offline';return false}
}
async function api(path,data,retry=true){
 let r;try{r=await Pocket.fetch(path,{method:'POST',headers:{'X-Token':TOKEN,...(data instanceof FormData?{}:{'Content-Type':'application/json'})},body:data instanceof FormData?data:JSON.stringify(data||{})})}catch(e){await checkConnection();throw Error('浏览器处理失败，请刷新重试，原文件未改变')}
 if(r.status===403&&retry&&await checkConnection())return api(path,data,false);
 if(!r.ok){let message=r.status===413?'文件超过 50 MB，请先缩小文件':'操作失败（'+r.status+'）';try{message=(await r.json()).error||message}catch{}throw Error(message)}return r
}
function fresh(role){let p=presets[role];return{preset:role,format:p.formats[0],target:p.defaultTarget||p.kb,sharpness:0,level:'low',fit:'contain',zoom:1,panx:.5,pany:.5,frame:0,background:'#e4ebd5'}}
function current(){return items.find(i=>i.key===selected)}
function dirty(i){i.result=null;i.error='';renderResults()}
function options(i){let o={...i.options};if(o.fit==='crop')o.crop=cropBox(i);return o}
function cropBox(i){let o=i.options,p=presets[o.preset],base=Math.max(p.width/i.width,p.height/i.height)*o.zoom;let w=p.width/base/i.width,h=p.height/base/i.height;return{x:Math.max(0,(1-w)*o.panx),y:Math.max(0,(1-h)*o.pany),w:Math.min(1,w),h:Math.min(1,h)}}
function paint(){let i=current();if(!i||!img)return;let o=i.options,p=presets[o.preset];const previewScale=900/Math.max(p.width,p.height);canvas.width=Math.round(p.width*previewScale);canvas.height=Math.round(p.height*previewScale);ctx.setTransform(previewScale,0,0,previewScale,0,0);canvas.style.aspectRatio=`${p.width}/${p.height}`;canvas.style.width=`min(100%, ${360*p.width/p.height}px)`;canvas.style.height='auto';ctx.clearRect(0,0,p.width,p.height);
 const opaque=p.alpha==='opaque'||o.format==='JPEG';if(opaque){ctx.fillStyle=o.background;ctx.fillRect(0,0,p.width,p.height)}else{const tile=Math.max(p.width,p.height)/30;for(let y=0;y<p.height;y+=tile)for(let x=0;x<p.width;x+=tile){ctx.fillStyle=((Math.round(x/tile)+Math.round(y/tile))%2)?'#e0e6d9':'#fff';ctx.fillRect(x,y,tile,tile)}}
 if(o.fit==='crop'){let b=cropBox(i);ctx.drawImage(img,b.x*img.width,b.y*img.height,b.w*img.width,b.h*img.height,0,0,p.width,p.height)}else{let r=Math.min(p.width/img.width,p.height/img.height),w=img.width*r,h=img.height*r;ctx.drawImage(img,(p.width-w)/2,(p.height-h)/2,w,h)}
 $('#canvaslabel').textContent=o.fit==='crop'?'拖动图片取景 · 边缘之外不会导出':'完整保留 · 留边不拉伸';
}
async function loadImage(){const i=current();let generation=++imageGeneration;img=null;ctx.clearRect(0,0,canvas.width,canvas.height);if(!i)return;let next=new Image();next.onload=()=>{if(generation!==imageGeneration)return;img=next;paint()};next.onerror=()=>{if(generation===imageGeneration)toast('预览加载失败，请重新导入素材')};try{const url=await Pocket.frame(i.id,i.options.frame);if(generation===imageGeneration)next.src=url}catch(e){if(generation===imageGeneration)toast(e.message)}}
function renderPresets(){let role=current()?.options.preset||currentRole;$('#presets').innerHTML=['sticker_static','sticker_dynamic','banner','cover','icon','reward_guide','reward_thanks'].map(id=>[id,presets[id]]).map(([id,p])=>`<button class="preset ${id===role?'active':''}" data-role="${id}" ${busy?'disabled':''}><b>${esc(p.label)}</b><span>${p.width} × ${p.height} · ${p.kb} KB</span></button>`).join('')}
function renderList(){let count=items.length;$('#count').textContent=count;$('#items').innerHTML=items.map(i=>`<div class="asset ${i.key===selected?'active':''}" role="button" tabindex="0" data-key="${i.key}" aria-label="编辑 ${esc(i.name)}"><img src="${i.thumb}" alt=""><div><strong>${esc(i.name)}</strong><small>${esc(presets[i.options.preset].label)} · ${i.frames} 帧</small>${i.error?`<small class="error">${esc(i.error)}</small>`:''}</div><button class="remove text" aria-label="移除 ${esc(i.name)}" data-remove="${i.key}" ${busy?'disabled':''}>×</button></div>`).join('');let stickers=items.filter(i=>i.options.preset.startsWith('sticker_')),types=new Set(stickers.map(i=>i.options.preset));$('#album').textContent=stickers.length?`表情 ${stickers.length} 张 · ${stickers.length>=8&&stickers.length<=24?'数量在 8–24 张范围内':'专辑需 8–24 张'}${types.size>1?' · 当前混有动静态，请统一':''}`:'表情专辑：8–24 张，同一套统一静态或动态。'}
function settings(){let i=current(),o=i?.options||fresh(currentRole),p=presets[o.preset];$('#roleTitle').textContent=p.label;$('#spec').textContent=`${p.width} × ${p.height} px · 小于 ${p.kb} KB`;$('#dimensions').textContent=`${p.width} × ${p.height} px`;$('#guidance').textContent=p.notes;$('#format').innerHTML=p.formats.map(f=>`<option value="${f}">${f==='JPEG'?'JPG':f}</option>`).join('');$('#format').value=o.format;$('#target').value=o.target;$('#target').max=p.kb;$('#level').value=o.level;$('#levelfield').hidden=o.preset==='icon';$('#iconquality').hidden=o.preset!=='icon';$('#sharpness').value=o.sharpness||0;$('#background').value=o.background;$('#bgfield').hidden=p.alpha!=='opaque'&&o.format!=='JPEG';$('#transparency').textContent=p.alpha==='required'?'必须有透明背景。仅转成 PNG 不会去掉原图白底；本工具不自动抠图，导出后检查透明像素；透明留边不代表主体白底已去除。':p.alpha==='opaque'?'自动合成不透明底色；横幅建议使用与主体协调的非白色背景。':'';
 $('#empty').hidden=!!i;$('#edit').hidden=!i;$('#export').disabled=busy||!i;$('#batch').disabled=busy||!items.length;document.querySelectorAll('[data-fit]').forEach(b=>b.classList.toggle('active',b.dataset.fit===o.fit));$('#cropcontrols').hidden=o.fit!=='crop';$('#zoom').value=o.zoom;$('#zoomvalue').textContent=o.zoom.toFixed(2)+'×';$('#panx').value=o.panx;$('#pany').value=o.pany;
 if(i){$('#editorTitle').textContent=i.name;$('#source').textContent=`原图 ${i.width} × ${i.height} · ${size(i.bytes)}`;$('#framecontrols').hidden=i.frames<2;$('#frame').max=i.frames-1;$('#frame').value=o.frame;$('#framevalue').textContent=`${o.frame+1} / ${i.frames}`;$('#framehint').textContent=p.animation===false||o.format!=='GIF'?'导出当前选中的这一帧。':'选帧只用于检查构图；导出保留全部动画帧并循环播放。'}
 renderPresets();renderList();}
function select(key){if(busy)return;selected=key;settings();loadImage()}
function renderResults(){let done=items.filter(i=>i.result);$('#resultcount').textContent=done.length;$('#zip').disabled=$('#save').disabled=busy||!done.length;$('#results').innerHTML=done.map(i=>{let r=i.result;return`<div class="result"><img class="${r.preset==='icon'?'native-icon':''}" src="${r.outputURL}" alt="${esc(presets[i.options.preset].label)}成品"><div class="info"><strong>${esc(r.outputName)}</strong><small>${size(r.bytes)} · ${r.width} × ${r.height} · ${r.frames} 帧${r.warning?' · '+esc(r.warning):''}${r.encoding?' · '+esc(r.encoding):''}</small><div class="checks">${(r.checks||[]).map(c=>`<span class="check ${c.ok?'':'fail'}">${c.ok?'✓':'!'} ${esc(c.label)}</span>`).join('')}</div>${r.compatible?'':'<small class="error">存在未满足项，调整后再上传微信。</small>'}</div><div class="row"><button class="small" data-preview="${i.key}">预览</button><button class="small" data-download="${i.key}">下载</button></div></div>`}).join('')}
async function addFiles(fs){
 if(busy||importing){toast('正在处理，请稍候再添加');return}
 importing=true;$('#uploadStatus').textContent='正在准备导入…';let added=0,failures=[];
 try{
  if(!await checkConnection())throw Error('图片引擎暂不可用，请刷新后重新选择文件。');
  if(!Object.keys(presets).length){let r=await Pocket.fetch('/api/wechat/presets');if(!r.ok)throw Error('无法加载素材规格');presets=await r.json()}
  for(let [index,f] of fs.entries()){
   $('#uploadStatus').textContent=`正在导入 ${index+1}/${fs.length}：${f.name}`;
   if(!/\.(gif|jpe?g|png|webp|apng|avif|bmp|tiff?)$/i.test(f.name)&&!f.type.startsWith('image/')){failures.push(f.name+'：不支持该类型');continue}
   if(f.size>50*1024*1024){failures.push(f.name+'：超过 50 MB');continue}
   try{let form=new FormData();form.append('file',f);let info=await(await api('/api/inspect',form)).json();let i={...info,key:crypto.randomUUID(),options:fresh(currentRole)};if(currentRole==='sticker_static'&&info.frames>1)i.options=fresh('sticker_dynamic');items.push(i);select(i.key);added++}catch(e){failures.push(f.name+'：'+e.message)}
  }
  $('#uploadStatus').textContent=`已导入 ${added} 张`+(failures.length?'。未导入：'+failures.join('；'):'，可以开始取景制作。');
 }catch(e){$('#uploadStatus').textContent=e.message;toast(e.message)}finally{importing=false;if(Object.keys(presets).length){renderList();settings()}}
}
$('#add').onclick=$('#uploadFiles').onclick=()=>$('#files').click();$('#addfolder').onclick=()=>$('#folders').click();for(let id of ['files','folders'])$('#'+id).onchange=e=>{addFiles([...e.target.files]);e.target.value=''};
async function walk(entry){if(entry.isFile)return new Promise(r=>entry.file(f=>r([f]),()=>r([])));if(entry.isDirectory){let rd=entry.createReader(),out=[];while(true){let entries=await new Promise((r,j)=>rd.readEntries(r,j));if(!entries.length)return out;for(let e of entries)out.push(...await walk(e))}}return[]}
$('#drop').ondragover=e=>{e.preventDefault();$('#drop').classList.add('over')};$('#drop').ondragleave=()=>$('#drop').classList.remove('over');$('#drop').ondrop=async e=>{e.preventDefault();$('#drop').classList.remove('over');try{let entries=[...e.dataTransfer.items].map(x=>x.webkitGetAsEntry?.()).filter(Boolean);let fs=[];if(entries.length){for(let entry of entries)fs.push(...await walk(entry))}else fs=[...e.dataTransfer.files];await addFiles(fs)}catch(e){toast('文件夹读取失败：'+e.message)}};
$('#presets').onclick=e=>{let b=e.target.closest('[data-role]');if(!b||busy)return;currentRole=b.dataset.role;let i=current();if(i){i.options=fresh(currentRole);dirty(i)}settings();loadImage()};
$('#items').onclick=e=>{if(busy)return;let r=e.target.closest('[data-remove]');if(r){items=items.filter(i=>i.key!==r.dataset.remove);if(selected===r.dataset.remove)selected=items[0]?.key||null;settings();renderResults();loadImage();return}let b=e.target.closest('[data-key]');if(b)select(b.dataset.key)};$('#items').onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.key){e.preventDefault();select(e.target.dataset.key)}};
for(let field of ['format','target','level','background','sharpness'])$('#'+field).onchange=()=>{let i=current();if(!i||busy)return;if(field==='target'&&!$('#target').checkValidity()){toast('请设置有效上限，不能超过该用途的截图阈值');$('#target').value=i.options.target;return}i.options[field]=(field==='target'||field==='sharpness')?Number($('#'+field).value):$('#'+field).value;dirty(i);settings();paint()};
$('#target').oninput=()=>{let i=current();if(i&&!busy&&$('#target').value&&$('#target').checkValidity()){i.options.target=Number($('#target').value);dirty(i)}};
document.querySelectorAll('[data-fit]').forEach(b=>b.onclick=()=>{let i=current();if(!i||busy)return;i.options.fit=b.dataset.fit;dirty(i);settings();paint()});
for(let field of ['zoom','panx','pany'])$('#'+field).oninput=()=>{let i=current();if(!i||busy)return;i.options[field]=Number($('#'+field).value);$('#zoomvalue').textContent=i.options.zoom.toFixed(2)+'×';dirty(i);paint()};
$('#reset').onclick=()=>{let i=current();if(!i)return;Object.assign(i.options,{zoom:1,panx:.5,pany:.5});dirty(i);settings();paint()};$('#frame').oninput=()=>{let i=current();if(!i||busy)return;i.options.frame=Number($('#frame').value);$('#framevalue').textContent=`${i.options.frame+1} / ${i.frames}`;dirty(i);loadImage()};
canvas.onpointerdown=e=>{let i=current();if(!i||busy||i.options.fit!=='crop')return;canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,px:i.options.panx,py:i.options.pany}};
canvas.onpointermove=e=>{let i=current();if(!drag||!i)return;let o=i.options,b=cropBox(i),rect=canvas.getBoundingClientRect();let dx=(e.clientX-drag.x)/rect.width*b.w,dy=(e.clientY-drag.y)/rect.height*b.h;o.panx=b.w>=.999999?.5:Math.max(0,Math.min(1,drag.px-dx/(1-b.w)));o.pany=b.h>=.999999?.5:Math.max(0,Math.min(1,drag.py-dy/(1-b.h)));$('#panx').value=o.panx;$('#pany').value=o.pany;dirty(i);paint()};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
$('#duplicate').onclick=()=>{let i=current();if(!i||busy)return;let copy={...i,key:crypto.randomUUID(),options:{...i.options},result:null};items.push(copy);select(copy.key);toast('已复制，选择上方用途即可制作另一种素材')};
function lock(on){busy=on;document.querySelectorAll('button,input,select').forEach(e=>e.disabled=on);settings();renderResults()}
async function run(i){i.error='';i.result=null;let form=new FormData();form.append('asset',i.id);form.append('options',JSON.stringify(options(i)));let j=await(await api('/api/jobs',form)).json();while(['queued','processing'].includes(j.status)){$('#progress').textContent=`${i.name} · ${j.message} ${j.progress}%`;await new Promise(r=>setTimeout(r,500));let r=await Pocket.fetch('/api/jobs/'+j.id);if(!r.ok)throw Error('无法读取任务状态');j=await r.json()}if(j.status!=='done')throw Error(j.message);i.result=j;$('#progress').textContent=`${i.name} · ${j.message}`;renderResults()}
async function produce(list){if(busy)return;lock(true);try{for(let i of list){try{await run(i)}catch(e){i.error=e.message;toast(i.name+'：'+e.message);renderList()}}}finally{lock(false)}}
$('#export').onclick=()=>{let i=current();if(i)produce([i])};$('#batch').onclick=()=>produce([...items]);
function download(url,name){let a=document.createElement('a');a.href=Pocket.url(url);a.download=name;document.body.append(a);a.click();a.remove()}
$('#results').onclick=e=>{let p=e.target.closest('[data-preview]'),d=e.target.closest('[data-download]');if(p){let i=items.find(i=>i.key===p.dataset.preview),r=i.result;$('#resultTitle').textContent=presets[i.options.preset].label+' · 实际成品（原尺寸）';$('#resultImage').src=r.outputURL;$('#resultMeta').textContent=`${size(r.bytes)} · ${r.width} × ${r.height} · ${r.frames} 帧 · ${r.compatible?'技术规格通过，内容仍需自行检查':'有未满足项，请检查'}`;$('#resultDialog').showModal()}if(d){let r=items.find(i=>i.key===d.dataset.download).result;download('/api/download/'+r.id,r.outputName)}};$('#close').onclick=()=>$('#resultDialog').close();
const ids=()=>items.filter(i=>i.result).map(i=>i.result.id);
$('#zip').onclick=async()=>{try{let r=await api('/api/zip',{ids:ids()}),u=URL.createObjectURL(await r.blob());download(u,'微信表情素材.zip');setTimeout(()=>URL.revokeObjectURL(u),30000)}catch(e){toast(e.message)}};
$('#save').onclick=async()=>{try{toast(await Pocket.save(ids()))}catch(e){if(e.name!=='AbortError')toast(e.message)}};
setInterval(()=>{if(!busy&&!importing)checkConnection()},15000);
(async()=>{try{await checkConnection();let r=await Pocket.fetch('/api/wechat/presets');if(!r.ok)throw Error('服务连接失败');presets=await r.json();settings();renderResults()}catch(e){toast(e.message)}})();
